create extension if not exists "pgcrypto";
create type user_role as enum ('SUPER_ADMIN','COLLECTION_MANAGER','ACCOUNT_MANAGER','VIEWER');
create type donation_status as enum ('PENDING','VERIFIED','FAILED','REFUNDED','CANCELLED');
create type withdrawal_status as enum ('REQUESTED','APPROVED','REJECTED','COMPLETED');
create table mandals(id uuid primary key default gen_random_uuid(), name text not null, address text, contact_number text, festival_year int not null, logo_url text, created_at timestamptz default now());
create table users(id uuid primary key references auth.users(id), mandal_id uuid references mandals(id), role user_role not null default 'VIEWER', full_name text, created_at timestamptz default now());
create table donors(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), full_name text not null, mobile text not null, email text, address text, created_at timestamptz default now());
create table donations(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), donor_id uuid references donors(id), receipt_number text unique, amount numeric(12,2) not null check(amount>0), currency text default 'INR', payment_method text not null, payment_provider text, payment_id text unique, transaction_id text unique, status donation_status not null default 'PENDING', donor_name_snapshot text not null, donor_mobile_snapshot text not null, donor_address_snapshot text, created_at timestamptz default now(), verified_at timestamptz, verified_by uuid references users(id));
create table receipts(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), donation_id uuid unique references donations(id), receipt_number text unique not null, pdf_url text, created_at timestamptz default now());
create table expenses(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), title text not null, category text not null, amount numeric(12,2) not null check(amount>0), description text, bill_url text, created_by uuid references users(id), created_at timestamptz default now());
create table withdrawals(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), amount numeric(12,2) not null check(amount>0), purpose text not null, status withdrawal_status not null default 'REQUESTED', requested_by uuid references users(id), approved_by uuid references users(id), completed_at timestamptz, supporting_document_url text, created_at timestamptz default now());
create table transactions(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), transaction_id text unique not null, type text not null, description text, income numeric(12,2) default 0, expense numeric(12,2) default 0, running_balance numeric(12,2), created_by uuid references users(id), reversed_at timestamptz, reversal_reason text, created_at timestamptz default now());
create table audit_logs(id uuid primary key default gen_random_uuid(), user_id uuid references users(id), action text not null, entity_type text not null, entity_id uuid, old_data jsonb, new_data jsonb, reason text, created_at timestamptz default now());
create table settings(id uuid primary key default gen_random_uuid(), mandal_id uuid references mandals(id), key text not null, value jsonb not null, unique(mandal_id,key));
create index on donations(receipt_number); create index on donors(mobile); create index on donations(transaction_id); create index on donations(payment_id); create index on donations(created_at); create index on donations(status); create index on expenses(created_at); create index on withdrawals(status);
alter table users enable row level security; alter table mandals enable row level security; alter table donors enable row level security; alter table donations enable row level security; alter table receipts enable row level security; alter table expenses enable row level security; alter table withdrawals enable row level security; alter table transactions enable row level security; alter table audit_logs enable row level security; alter table settings enable row level security;
create policy mandal_isolation_donations on donations using (mandal_id in (select mandal_id from users where id=auth.uid()));
create policy mandal_isolation_donors on donors using (mandal_id in (select mandal_id from users where id=auth.uid()));
create policy mandal_isolation_expenses on expenses using (mandal_id in (select mandal_id from users where id=auth.uid()));
create policy mandal_isolation_withdrawals on withdrawals using (mandal_id in (select mandal_id from users where id=auth.uid()));
create policy mandal_isolation_transactions on transactions using (mandal_id in (select mandal_id from users where id=auth.uid()));
